import{_ as t,o,c as r,a2 as s}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"ホットキー(設定ページ)","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/user-guide/settings/hotkeys-page.md","filePath":"ja-JP/user-guide/settings/hotkeys-page.md","lastUpdated":1785993908000}'),a={name:"ja-JP/user-guide/settings/hotkeys-page.md"};function l(n,e,c,d,i,g){return o(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="ホットキー-設定ページ" tabindex="-1">ホットキー(設定ページ) <a class="header-anchor" href="#ホットキー-設定ページ" aria-label="Permalink to &quot;ホットキー(設定ページ)&quot;">​</a></h1><p><strong>グローバル</strong>、<strong>プラグインアクション</strong>、<strong>プロセスブラックリスト</strong> の 3 つのタブがあります。各ショートカットが実際に何をするかについては <a href="./../hotkeys.html">ホットキー</a> ページを参照してください。このページでは設定 UI 自体について説明します。</p><h2 id="グローバル" tabindex="-1">グローバル <a class="header-anchor" href="#グローバル" aria-label="Permalink to &quot;グローバル&quot;">​</a></h2><p><strong>グローバルホットキー</strong> グループ:</p><ul><li><strong>クイック検索の表示/非表示</strong> — レコーダーコントロール。単独の修飾キー(ダブルタップモード、デフォルトは <code>Ctrl</code>)、またはフルコンボのいずれかを受け付けます。その横にある <strong>フルスクリーンアプリにフォーカスがある間も応答する</strong> — チェックボックス、デフォルトでオフ — をオンにすると、このホットキー(および Quick Switch、インライン検索の起動)は、下の <a href="#process-blacklist">プロセスブラックリスト</a> で説明されている自動的なフルスクリーン除外の対象から外れます。</li><li><strong>Quick Switch</strong> — デフォルト <code>Ctrl+G</code>。</li></ul><p><strong>ファンクションキー</strong> グループ:</p><ul><li>次の項目 (<code>Ctrl+N</code>)、前の項目 (<code>Ctrl+P</code>)、結果へジャンプする修飾キー(デフォルト <code>Ctrl</code>、数字 1〜9 と組み合わせ)、アクションメニューを開く (<code>Ctrl+O</code>)、選択項目から補完 (<code>Ctrl+Tab</code>)、QuickLook (<code>Alt+P</code>)、前/次のキーワード履歴 (<code>Alt+Up</code> / <code>Alt+Down</code>)、キーワード履歴エントリを削除 (<code>Ctrl+Delete</code>)、フルウィンドウを開く(デフォルト <code>Ctrl+F</code> — 現在のクエリを引き継いだままフルウィンドウを直接開きます。クイックウィンドウ自身のロゴを左クリックして「メインウィンドウを表示」を選ぶのと同じ効果を、その追加のクリックなしで得られます)。</li><li>ここにあるすべてのレコーダーは、単独の <code>Tab</code> のようなキーを含む、どのキーやコンボでも受け付けます。そのキーにハードコードされたデフォルトの意味があっても、この割り当てが優先されます。</li></ul><p><strong>クイックナビゲーション</strong> グループ:</p><ul><li><strong>空白部分でのダブル左クリック</strong> — チェックボックス、デフォルトでオン。</li><li><strong>空白部分での中央クリック</strong> — チェックボックス、デフォルトでオン。</li></ul><h2 id="プラグインアクション" tabindex="-1">プラグインアクション <a class="header-anchor" href="#プラグインアクション" aria-label="Permalink to &quot;プラグインアクション&quot;">​</a></h2><p>プラグインが登録した各アクション(例: パスをコピー、管理者として実行)ごとに 1 つのエントリがあり、プラグイン名でグループ化され、それぞれに専用のホットキーレコーダーがあります。変更するまではプラグイン自身が提案するデフォルトにフォールバックします。</p><h2 id="process-blacklist" tabindex="-1">プロセスブラックリスト <a class="header-anchor" href="#process-blacklist" aria-label="Permalink to &quot;プロセスブラックリスト {#process-blacklist}&quot;">​</a></h2><p>実行可能ファイル名(例: <code>game.exe</code>)を追加すると、そのプロセスが前面にフォーカスされている間、Lertaro のグローバルホットキー、キーストロークの割り込み、クイックナビゲーションのダブルクリック/中央クリックのマウストリガーがすべて抑制されます。大文字小文字を区別せず、<code>.exe</code> の拡張子は省略可能です。<strong>インデックス</strong> の下にある除外ルールと同じ、単体追加/一括編集のパターンをサポートしています: 単一エントリ用のテキストボックスと <strong>プロセスを追加</strong>、既存エントリのリスト、<strong>テキストを生成</strong> / <strong>テキストを適用</strong> を備えた一括編集用テキストボックスです。</p><p>これはフルスクリーンゲームや、生のキーボード入力を奪う他のアプリとのホットキー競合に対する対処法です。詳しくは <a href="./../troubleshooting.html#グローバルホットキーが反応しない">トラブルシューティング</a> を参照してください。実際に本当のフルスクリーンになっている前面アプリは、ここにエントリを追加しなくても自動的に同じ扱いを受けます。ただし(<strong>グローバル</strong> の下、クイック検索の表示/非表示の隣にある)<strong>フルスクリーンアプリにフォーカスがある間も応答する</strong> がオンになっている場合を除きます。この設定をオンにすると、その除外が完全に無効になります。いずれの場合も、アクティブなファイルダイアログは常に除外対象なので、そこではクイックナビゲーションが機能し続けます。</p>',14)])])}const u=t(a,[["render",l]]);export{p as __pageData,u as default};
